package glitch

import data.glitch_lib

password_keywords := {
    "password", "passwd", "pwd", "pass",
    "secret", "secret_key", "secretkey",
    "credentials", "creds", "auth_token",
    "api_key", "apikey", "api_secret",
    "private_key", "privatekey",
    "access_key", "accesskey",
    "admin_password", "root_password",
    "master_password", "master_pwd",
    "connection_string", "conn_string"
}

# Check if field name matches password keywords
is_password_field(name) {
    lower_name := lower(name)
    contains(lower_name, password_keywords[_])
}

# Check if value is a literal string (not a reference to external source)
is_literal_credential(value) {
    value.ir_type == "String"
    count(value.value) > 0
    not is_external_reference(value.value)
}

# Check if value indicates external secret store reference
is_external_reference(str) {
    regex.match("(?i)data\\.|var\\.|vault_|aws_secretsmanager|azurerm_key_vault|google_secret_manager|random_", str)
}

# Check for default password patterns
is_default_password(value) {
    value.ir_type == "String"
    default_patterns := {"admin", "password", "123456", "changeme", "default", "test", "secret", "root", "toor", "letmein", "welcome"}
    contains(lower(value.value), default_patterns[_])
}

# Extract all nested values from complex structures
extract_values(node) = values {
    values := {v |
        walk(node, [_, n])
        n.ir_type == "String"
        v := n
    }
}

# Check attributes in atomic units recursively for password fields
check_nested_passwords(attr, parent_path) = results {
    results := {r |
        # Direct attribute with password field name and literal value
        is_password_field(attr.name)
        is_literal_credential(attr.value)

        r := {
            "type": "sec_hard_pass",
            "element": attr,
            "path": parent_path,
            "description": "Use of Hard-coded Password - Passwords should not be embedded directly in resource definitions. Use external secret stores instead. (CWE-259)"
        }
    }
}

# Check for password fields in Hash values (nested configurations)
check_hash_passwords(hash, parent_path, parent_name) = results {
    results := {r |
        hash.ir_type == "Hash"
        [key, val] := hash.value[_]

        # Key could be a String or other expression
        key_name := get_key_name(key)
        is_password_field(key_name)
        is_literal_credential(val)

        r := {
            "type": "sec_hard_pass",
            "element": val,
            "path": parent_path,
            "description": "Use of Hard-coded Password - Passwords should not be embedded directly in resource definitions. Use external secret stores instead. (CWE-259)"
        }
    }
}

# Extract key name from various key types
get_key_name(key) = name {
    key.ir_type == "String"
    name := key.value
} else = name {
    key.ir_type == "VariableReference"
    name := key.value
} else = name {
    name := ""
}

# Recursively check values for password patterns
check_value_passwords(value, parent_path, context_name) = results {
    results := {r |
        # Check direct string in password context
        is_password_field(context_name)
        is_literal_credential(value)

        r := {
            "type": "sec_hard_pass",
            "element": value,
            "path": parent_path,
            "description": "Use of Hard-coded Password - Passwords should not be embedded directly in resource definitions. Use external secret stores instead. (CWE-259)"
        }
    }
}

# Check variables for hardcoded passwords
check_variable_passwords(var, parent_path) = results {
    results := {r |
        is_password_field(var.name)
        is_literal_credential(var.value)

        r := {
            "type": "sec_hard_pass",
            "element": var,
            "path": parent_path,
            "description": "Use of Hard-coded Password - Passwords should not be embedded directly in resource definitions. Use external secret stores instead. (CWE-259)"
        }
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check atomic units
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    # Check direct attributes
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    # Check for password field with literal value
    is_password_field(attr.name)
    is_literal_credential(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Passwords should not be embedded directly in resource definitions. Use external secret stores instead. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check for nested password values in Hash attributes
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    # Recursively check Hash values for password fields
    attr.value.ir_type == "Hash"
    [key, val] := attr.value.value[_]

    key_name := get_key_name(key)
    is_password_field(key_name)
    is_literal_credential(val)

    result := {
        "type": "sec_hard_pass",
        "element": val,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Passwords should not be embedded directly in resource definitions. Use external secret stores instead. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables at unit block level
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    is_password_field(var.name)
    is_literal_credential(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Passwords should not be embedded directly in variable definitions. Use external secret stores instead. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check for passwords in Array values (e.g., connection strings list)
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    attr.value.ir_type == "Array"
    elem := attr.value.value[_]

    is_password_field(attr.name)
    is_literal_credential(elem)

    result := {
        "type": "sec_hard_pass",
        "element": elem,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Passwords should not be embedded directly in resource definitions. Use external secret stores instead. (CWE-259)"
    }
}

